            dom.style.backgroundImage = "url("+block.image.thumb.url+")"
            dom.style.height = height
            dom.style.backgroundSize = size;
            dom.style.paddingLeft = padded_size;
            dom.style.backgroundRepeat = "no-repeat";
          }
        }

        return { dom }

      }
    }

  })

}

